import{_ as a,o as i,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"创游类型转换现象整理","description":"","frontmatter":{},"headers":[],"relativePath":"社区分析/专题研究/创游类型转换现象整理.md","filePath":"社区分析/专题研究/创游类型转换现象整理.md","lastUpdated":1776864657000}'),h={name:"社区分析/专题研究/创游类型转换现象整理.md"};function d(t,l,o,n,c,s){return i(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游类型转换现象整理" tabindex="-1">创游类型转换现象整理 <a class="header-anchor" href="#创游类型转换现象整理" aria-label="Permalink to “创游类型转换现象整理”">​</a></h1><p>本文件根据 <code>资料/其他用户给的解析.txt</code> 中与“类型转换”相关的观察拆分整理，目标是单独沉淀创游脚本系统里一些值得研究的类型行为线索。</p><blockquote><p>说明：本文件属于社区观察与推测整理，不代表官方规范。</p></blockquote><h2 id="_1-研究背景" tabindex="-1">1. 研究背景 <a class="header-anchor" href="#_1-研究背景" aria-label="Permalink to “1. 研究背景”">​</a></h2><p>原文中，作者长期尝试一件事：</p><ul><li>把“文本类型”转换为“脚本类型”</li></ul><p>在这个过程中，顺带观察到了很多类型系统相关现象，包括：</p><ul><li>某些类型可以隐式转换</li><li>某些类型转换会失败</li><li>布尔值在数字环境下会表现为 <code>1/0</code></li><li>文本拼接几乎能接收任意类型</li><li>但脚本类型似乎无法由文本直接构造</li></ul><h2 id="_2-已观察到的显式现象" tabindex="-1">2. 已观察到的显式现象 <a class="header-anchor" href="#_2-已观察到的显式现象" aria-label="Permalink to “2. 已观察到的显式现象”">​</a></h2><h3 id="_2-1-布尔值进入数字上下文" tabindex="-1">2.1 布尔值进入数字上下文 <a class="header-anchor" href="#_2-1-布尔值进入数字上下文" aria-label="Permalink to “2.1 布尔值进入数字上下文”">​</a></h3><p>原文提到：</p><ul><li>在一个数字数组里放置真假值</li><li>显示这个数组内容时</li><li><code>true</code> 会显示成 <code>1</code></li><li><code>false</code> 会显示成 <code>0</code></li></ul><h3 id="可能含义" tabindex="-1">可能含义 <a class="header-anchor" href="#可能含义" aria-label="Permalink to “可能含义”">​</a></h3><p>这说明在某些上下文中，创游存在布尔到数字的隐式映射：</p><ul><li><code>true -&gt; 1</code></li><li><code>false -&gt; 0</code></li></ul><p>这非常像许多脚本语言中的常见隐式转换逻辑。</p><h2 id="_3-任意类型-文本-相对容易" tabindex="-1">3. “任意类型 -&gt; 文本”相对容易 <a class="header-anchor" href="#_3-任意类型-文本-相对容易" aria-label="Permalink to “3. “任意类型 -&gt; 文本”相对容易”">​</a></h2><p>原文指出：</p><ul><li>文本拼接积木的参数几乎可以填写任何类型</li><li>并把它们转换成文本类型</li></ul><h3 id="这说明" tabindex="-1">这说明 <a class="header-anchor" href="#这说明" aria-label="Permalink to “这说明”">​</a></h3><p>创游至少对“转文本”提供了非常宽松的入口。</p><h3 id="实际意义" tabindex="-1">实际意义 <a class="header-anchor" href="#实际意义" aria-label="Permalink to “实际意义”">​</a></h3><p>这类机制通常用于：</p><ul><li>日志显示</li><li>调试输出</li><li>文本 UI 展示</li><li>说明信息拼接</li></ul><p>也就是说，<code>任意值 -&gt; 可显示文本</code> 这条路径在系统里是被重点支持的。</p><h2 id="_4-文本-脚本-为什么难" tabindex="-1">4. “文本 -&gt; 脚本”为什么难 <a class="header-anchor" href="#_4-文本-脚本-为什么难" aria-label="Permalink to “4. “文本 -&gt; 脚本”为什么难”">​</a></h2><p>原文认为失败原因可能包括：</p><ol><li>脚本内部不是普通纯文本</li><li>生成脚本时可能依赖积木位置等结构信息</li><li>生成结果里包含类似哈希/随机标识的内容</li><li>文本中的引号和反斜杠会被系统转义</li><li>因而无法通过简单字符串替换来伪造脚本</li></ol><h3 id="结构理解" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解" aria-label="Permalink to “结构理解”">​</a></h3><p>这意味着“脚本类型”大概率具有以下特征之一：</p><ul><li>不是单纯字符串</li><li>或虽然可显示为字符串，但内部依赖额外元数据</li><li>或必须通过专门生成器构造</li></ul><p>换句话说，看到脚本文本 ≠ 可以制造脚本对象。</p><h2 id="_5-为什么有时能转-有时不能转" tabindex="-1">5. 为什么有时能转，有时不能转 <a class="header-anchor" href="#_5-为什么有时能转-有时不能转" aria-label="Permalink to “5. 为什么有时能转，有时不能转”">​</a></h2><p>原文作者最大的困惑之一是：</p><ul><li>有时类型转换成功</li><li>有时转换失败</li></ul><h3 id="可能的解释方向" tabindex="-1">可能的解释方向 <a class="header-anchor" href="#可能的解释方向" aria-label="Permalink to “可能的解释方向”">​</a></h3><p>这很可能不是“同一种统一规则”，而是上下文驱动：</p><ul><li>在显示环境里，系统愿意自动转成文本</li><li>在数值环境里，布尔值可能会自动映射成数字</li><li>在脚本环境里，系统则要求严格结构</li></ul><h3 id="这说明什么" tabindex="-1">这说明什么 <a class="header-anchor" href="#这说明什么" aria-label="Permalink to “这说明什么”">​</a></h3><p>创游的类型系统可能并不是完全静态或完全强类型，而是：</p><ul><li>对某些常见场景宽松</li><li>对某些特殊对象严格限制</li><li>不同积木的参数槽位可能拥有不同兼容策略</li></ul><h2 id="_6-与静默失败问题的关系" tabindex="-1">6. 与静默失败问题的关系 <a class="header-anchor" href="#_6-与静默失败问题的关系" aria-label="Permalink to “6. 与静默失败问题的关系”">​</a></h2><p>类型转换研究和“有些错误不报错”其实是相互关联的。</p><p>如果系统在类型不匹配时：</p><ul><li>没有清晰报错</li><li>或内部悄悄吞掉异常</li><li>或直接给出默认值/空结果</li></ul><p>那么创作者看到的表象就会是：</p><ul><li>为什么它没反应？</li><li>为什么有时能用有时不能用？</li><li>为什么没有报错却没结果？</li></ul><p>这也是社区研究里反复出现的痛点。</p><h2 id="_7-可形成的实验方向" tabindex="-1">7. 可形成的实验方向 <a class="header-anchor" href="#_7-可形成的实验方向" aria-label="Permalink to “7. 可形成的实验方向”">​</a></h2><p>未来可以专门建立“类型转换实验表”，按以下方式测试：</p><h3 id="_7-1-基础值类型互转" tabindex="-1">7.1 基础值类型互转 <a class="header-anchor" href="#_7-1-基础值类型互转" aria-label="Permalink to “7.1 基础值类型互转”">​</a></h3><ul><li>数字 -&gt; 文本</li><li>文本 -&gt; 数字</li><li>布尔 -&gt; 数字</li><li>布尔 -&gt; 文本</li><li>文本 -&gt; 布尔</li></ul><h3 id="_7-2-容器类型" tabindex="-1">7.2 容器类型 <a class="header-anchor" href="#_7-2-容器类型" aria-label="Permalink to “7.2 容器类型”">​</a></h3><ul><li>数组里混放不同类型时如何显示</li><li>配置表能否进入数组</li><li>含属性/指令的特殊对象能否存入容器</li></ul><h3 id="_7-3-特殊对象类型" tabindex="-1">7.3 特殊对象类型 <a class="header-anchor" href="#_7-3-特殊对象类型" aria-label="Permalink to “7.3 特殊对象类型”">​</a></h3><ul><li>脚本类型能否被拼接、复制、显示</li><li>显示后的脚本文本能否反向导入</li><li>自定义组件属性是否允许跨类型写入</li></ul><h2 id="_8-对知识库的意义" tabindex="-1">8. 对知识库的意义 <a class="header-anchor" href="#_8-对知识库的意义" aria-label="Permalink to “8. 对知识库的意义”">​</a></h2><p>单独整理类型转换专题很有价值，因为它能解释很多“脚本看起来没错却跑不通”的问题。</p><p>特别适合回答这些问题：</p><ul><li>为什么 true 会变成 1？</li><li>为什么文本拼接什么都能接？</li><li>为什么文本不能直接变脚本？</li><li>为什么有时转换成功，有时失败？</li><li>创游是不是存在隐式类型转换？</li></ul><h2 id="_9-关键词" tabindex="-1">9. 关键词 <a class="header-anchor" href="#_9-关键词" aria-label="Permalink to “9. 关键词”">​</a></h2><ul><li>类型转换</li><li>隐式转换</li><li>布尔转数字</li><li>true 1</li><li>false 0</li><li>文本拼接</li><li>文本转脚本</li><li>脚本类型</li><li>转义</li><li>哈希标识</li><li>特殊对象</li></ul>',62)])])}const u=a(h,[["render",d]]);export{_ as __pageData,u as default};
